    js: "'use strict';\nconst $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));\nconst node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};\nconst svg=(tag,attrs={})=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,String(v)));return n;};\nconst clamp=(v,a,b)=>Math.max(a,Math.min(b,v));\nconst windows=new Map($$('[data-window]').map(w=>[w.dataset.window,w]));let z=3,space='explore',band='alpha';const positions={orbit:[.06,.05],signal:[.48,.2],notes:[.24,.51]};\nfunction setPosition(w,x,y){const r=$('#desktop').getBoundingClientRect(),wr=w.getBoundingClientRect();w.style.left=clamp(x,0,Math.max(0,1-wr.width/r.width))*100+'%';w.style.top=clamp(y,0,Math.max(0,1-wr.height/r.height))*100+'%';}\nfunction status(){const count=Array.from(windows.values()).filter(w=>!w.hidden).length;$('#os-status').textContent=count+' 个窗口 · '+(space==='focus'?'专注':'探索')+'模式';$$('[data-launch]').forEach(b=>b.setAttribute('aria-pressed',String(!windows.get(b.dataset.launch).hidden)));}\nfunction restore(){windows.forEach((w,k)=>{w.hidden=false;const p=positions[k];setPosition(w,p[0],p[1]);w.style.zIndex=++z;});status();}\nwindows.forEach(w=>{const h=w.querySelector('.window-head');let drag;h.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const r=$('#desktop').getBoundingClientRect(),b=w.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,wx:b.left-r.left,wy:b.top-r.top};w.style.zIndex=++z;h.setPointerCapture(e.pointerId);});h.addEventListener('pointermove',e=>{if(!drag)return;const r=$('#desktop').getBoundingClientRect();setPosition(w,(drag.wx+e.clientX-drag.x)/r.width,(drag.wy+e.clientY-drag.y)/r.height);});h.addEventListener('pointerup',()=>drag=null);h.addEventListener('pointercancel',()=>drag=null);w.addEventListener('pointerdown',()=>w.style.zIndex=++z);});\n$$('[data-close]').forEach(b=>b.addEventListener('click',()=>{windows.get(b.dataset.close).hidden=true;status();}));$$('[data-launch]').forEach(b=>b.addEventListener('click',()=>{const w=windows.get(b.dataset.launch);w.hidden=false;w.style.zIndex=++z;status();}));$$('[data-space]').forEach(b=>b.addEventListener('click',()=>{space=b.dataset.space;$$('[data-space]').forEach(c=>c.classList.toggle('active',c===b));if(space==='focus'){windows.forEach((w,k)=>{w.hidden=k!=='notes';});setPosition(windows.get('notes'),.14,.13);}else restore();status();}));$('#arrange').addEventListener('click',()=>{const mobile=matchMedia('(max-width:520px)').matches;windows.forEach((w,k)=>{const i=['orbit','signal','notes'].indexOf(k);w.hidden=false;setPosition(w,mobile?i*.075:.05+i*.21,mobile?i*.28:.03+i*.2);w.style.zIndex=++z;});status();});$('#restore').addEventListener('click',restore);\nfunction plot(){const s=$('#signal-chart');s.replaceChildren();[20,45,70].forEach(y=>s.append(svg('line',{x1:0,y1:y,x2:260,y2:y,stroke:'#8ca8bd1f'})));const f=band==='alpha'?2:band==='beta'?4:6;const pts=Array.from({length:130},(_,i)=>[i*2,47+Math.sin(i/130*Math.PI*2*f)*25*Math.sin(i/130*Math.PI)]);s.append(svg('polyline',{points:pts.map(p=>p.join(',')).join(' '),stroke:band==='gamma'?'#eac2a3':'#95cdd5','stroke-width':2,fill:'none'}));$('#band-label').textContent=band.toUpperCase();}\n$$('[data-band]').forEach(b=>b.addEventListener('click',()=>{band=b.dataset.band;$$('[data-band]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));plot();}));$('#orbital-angle').addEventListener('input',()=>{const a=Number($('#orbital-angle').value)*Math.PI/180;$('#satellite').setAttribute('cx',130+103*Math.cos(a));$('#satellite').setAttribute('cy',74+30*Math.sin(a));});$('#notes').addEventListener('input',()=>$('#note-count').textContent=$('#notes').value.length+' 字');$('#note-count').textContent=$('#notes').value.length+' 字';plot();restore();addEventListener('resize',()=>{if(space==='explore')restore();});",
